-- Örnek veri: "Örnek Atölye" çalışma alanı. Yalnız yerel geliştirme ve testler içindir; gerçek kişi içermez.
-- Kimlikler sabittir: uuid v5(6f1d3c5e-0b7a-4d59-9c36-2a4f8e1b7d10, anahtar). Anahtarlar (l-kitchen, c-deniz ...)
-- testlerde aynı işlevle üretilir (e2e/support.ts). Zamanlar yükleme anına göredir.
-- Bu dosya scripts/db.sh reset ile ve geliştirmede POST /api/dev/reset ile yüklenir.

-- Kullanıcılar. Yerelde auth şeması bir taklittir; gerçek Supabase'de kullanıcılar Auth üzerinden açılır.
-- Örnek kullanıcının deneme şifresi: "deneme-sifresi" (yalnız yerel geliştirme verisi).
-- Örnek kullanıcının deneme şifresi: "deneme-sifresi" (yalnız yerel geliştirme verisi).
update profiles set lang = 'tr', timezone = 'Europe/Istanbul';



update channels set is_demo = true where external_account_id like 'demo-%';



update conversations set unread_count = 2 where id = '4335d885-6075-55e5-9202-a0abcd5d3090';
update conversations set unread_count = 0 where id = '7aef84db-3257-5117-bf52-3a92572dccdb';
update conversations set unread_count = 0 where id = 'f6b2028a-0d1b-584d-874f-6a6de6396de5';



-- Mesaj ve görev tetikleyicileri lead'lerin güncellenme zamanını bugüne çekti; örnek zamanlar geri yazılır.
alter table leads disable trigger set_updated_at;
update leads set updated_at = now() + interval '-120 seconds' where id = 'cf2dbd95-f1be-5d42-945a-3d0c0396854a';
update leads set updated_at = now() + interval '-3600 seconds' where id = 'c0e11f32-fa2d-5f2c-bc27-e7f267d275cf';
update leads set updated_at = now() + interval '-18000 seconds' where id = '87765c7e-0a33-5f0a-aa5a-91eb4ddf9c42';
update leads set updated_at = now() + interval '-172800 seconds' where id = '7993aec0-8e8a-5780-a4d8-e8c34495f4df';
update leads set updated_at = now() + interval '-259200 seconds' where id = '9ff4a15d-7bd1-50ba-9340-bde916530f24';
update leads set updated_at = now() + interval '-518400 seconds' where id = 'c211a9da-6d76-5ffd-86ed-d4e916b373c1';
alter table leads enable trigger set_updated_at;

